PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE inspection_field_definition (
    id TEXT PRIMARY KEY,
    field_name TEXT NOT NULL,
    field_place TEXT NOT NULL,
    field_type TEXT NOT NULL
, expanded_by_default boolean);
COMMIT;
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE inspection_field_definition_value (
    id TEXT PRIMARY KEY,
    inspection_field_definition_id TEXT NOT NULL,
    value TEXT NOT NULL, default_implication varchar(255),
    FOREIGN KEY (inspection_field_definition_id)
        REFERENCES inspection_field_definition(id)
);
COMMIT;
